function getCardDevLevel(card) {
  if (!card) return 0;
  if (card.devLevel !== undefined) return card.devLevel;
  if (card.rarity === 'l') return 3;
  if (card.rarity === 'r') return 2;
  if (card.rarity === 'uc') return 1;
  return 0;
}

